import sys, io, json, os, unittest, importlib.abc, types, copy
from pathlib import Path
from unittest.mock import patch
WORK=Path('/tmp/filesystem-review-7352c1')
sys.dont_write_bytecode=True
sys.path[:0]=[str(WORK/'copied'),str(WORK/'copied/host')]
class Deny(importlib.abc.MetaPathFinder):
    def find_spec(self,fullname,path=None,target=None):
        if fullname=='modal' or fullname.startswith('modal.') or fullname in {'engine','cohort','constructor','curve'}:
            raise AssertionError('forbidden import: '+fullname)
sys.meta_path.insert(0,Deny())
import controller as c, test_transport as t, driver
import test_verify
stream=io.StringIO()
suite=unittest.defaultTestLoader.loadTestsFromModule(t)
suite.addTests(unittest.defaultTestLoader.loadTestsFromNames([
    'test_verify.Fixtures.test_custody_rejects_before_oracle',
    'test_verify.Fixtures.test_custody_extras_symlinks_and_duplicate_paths']))
result=unittest.TextTestRunner(stream=stream,verbosity=2).run(suite)
out={'tests_run':result.testsRun,'failures':len(result.failures),'errors':len(result.errors),'full_log':stream.getvalue(),'independent_cases':[]}
def case(name, fn):
    try:
        value=fn();out['independent_cases'].append({'name':name,'pass':True,'observation':value})
    except Exception as e:
        out['independent_cases'].append({'name':name,'pass':False,'error':repr(e)})
def api_mutant(kind):
    with t.tempfile.TemporaryDirectory() as root:
        def configure(sb):
            if kind=='obsolete-open-only':
                del sb.filesystem
                sb.open=lambda *a,**k: (_ for _ in ()).throw(AssertionError('obsolete open called'))
            elif kind=='reversed-write-signature':
                def reversed_write(remote_path,data):
                    if not isinstance(remote_path,str) or not isinstance(data,bytes):raise TypeError('wrong argument order')
                sb.filesystem.write_bytes=reversed_write
            elif kind=='reversed-copy-signature':
                def reversed_copy(local_path,remote_path):
                    if not isinstance(remote_path,str) or not remote_path.startswith('/work/result/'):raise TypeError('wrong argument order')
                sb.filesystem.copy_to_local=reversed_copy
        dest,record,sb=t.mocked_run(root,configure=configure)
        assert record['status']=='failed' and record['termination_ack'] is None and not record['collection_complete']
        assert record['vm_creates']==1 and record['engine_execs']==(1 if kind=='reversed-copy-signature' else 0)
        assert not (dest/'custody.json').exists()
        return {'error':record['error'],'engine_execs':record['engine_execs'],'vm_creates':record['vm_creates'],'custody':False,'retry':record['automatic_retry']}
for kind in ['obsolete-open-only','reversed-write-signature','reversed-copy-signature']:
    case(kind,lambda kind=kind:api_mutant(kind))
def metadata_mutant(kind):
    with t.tempfile.TemporaryDirectory() as root:
        def configure(sb):
            if kind=='nonbytes':sb.filesystem.read_bytes=lambda path:bytearray(b'{}')
            else:
                counts={}
                def mutate(path,info):
                    if path.endswith('build-info.json'):
                        counts[path]=counts.get(path,0)+1
                        if counts[path]==2:info.size+=1
                sb.filesystem.info_mutant=mutate
        dest,r,sb=t.mocked_run(root,configure=configure)
        assert r['status']=='failed' and r['engine_execs']==0 and r['termination_ack'] is None
        return r['error']
for kind in ['nonbytes','post-read-stat-size-change']:case('metadata-'+kind,lambda kind=kind:metadata_mutant(kind))
def multi_partial():
    with t.tempfile.TemporaryDirectory() as root:
        files={'raw/a':b'fixed F11 A','raw/b':b'fixed F11 B'};sb=t.Sandbox(files)
        entries=[{'path':n,'sha256':c.sha_bytes(b),'size':len(b)} for n,b in files.items()]
        entries[1]['sha256']='ff'*32
        dest=Path(root)/'collection'
        try:c.collect_stream(sb,dest,entries,{'max_file_bytes':100,'max_total_bytes':200})
        except ValueError as e:message=str(e)
        else:raise AssertionError('bad second hash accepted')
        assert (dest/'raw/a').read_bytes()==files['raw/a'] and not (dest/'raw/b').exists()
        assert (Path(root)/'collection.partial/1').read_bytes()==files['raw/b']
        assert not (dest/'custody.json').exists()
        return {'refusal':message,'verified_first_file_retained':True,'unverified_second_retained_only_partial':True}
case('multi-file-partial-refusal',multi_partial)
def extra_bounds():
    failures=[]
    one={'path':'raw/a','sha256':'00'*32,'size':9}
    for name,rows,lim in [('total',[one,{**one,'path':'raw/b'}],{'max_file_bytes':10,'max_total_bytes':17}),('count',[{**one,'path':f'raw/{n}'} for n in range(65)],{'max_file_bytes':10,'max_total_bytes':1000}),('bool-size',[{**one,'size':True}],{'max_file_bytes':10,'max_total_bytes':20})]:
        try:c.validate_entries(rows,lim)
        except ValueError as e:failures.append({'name':name,'refusal':str(e)})
        else:raise AssertionError(name+' accepted')
    return failures
case('independent-count-total-type-bounds',extra_bounds)
out['pass']=result.wasSuccessful() and all(x['pass'] for x in out['independent_cases'])
out['modal_loaded']=any(k=='modal' or k.startswith('modal.') for k in sys.modules)
out['candidate_modules_loaded']=[k for k in ['engine','cohort','constructor','curve'] if k in sys.modules]
assert not out['modal_loaded'] and not out['candidate_modules_loaded']
(WORK/'fixture-result.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps({k:v for k,v in out.items() if k!='full_log'},indent=2))
print(stream.getvalue())
sys.exit(0 if out['pass'] else 1)

